select case when carrier in ('Flash', 'FedEx') then 'core' else 'other' end as carrier_group, case when cost >= 79 then 'high' when cost >= 21 then 'mid' else 'low' end as cost_bucket, max(cost) as max_cost, concat_ws(', ', sort_array(collect_set(status))) as status_values from shipments where month(shipped_date) in (4, 6, 10) group by rollup(case when carrier in ('Flash', 'FedEx') then 'core' else 'other' end, case when cost >= 79 then 'high' when cost >= 21 then 'mid' else 'low' end)
